const TIME_LIMIT: int = 1926;
const OPENING_BUFFER: int = 120;
const TH15_FIREBALL_RED: int = 752;
const TH15_BIG_STAR_R: int = 720;

// st05bs:709-712: ANIM retreat is applied at fire; birth animation is omitted.
// VELTIME is collinear here: scalar 4 -> 7 over 30 ticks.
// funcSet2 applies ONLY to this mark-0 family; mark-1 stars have no such xf.
// globals16/17 publish the moon center in 1/64px units (safe Q16 range).
// set_life(1) retires at cleanup, so the cancellation tick still has collision.
xformdef MOON_ERASABLE {
    set_accel(0.1fx);
check_moon:
    set_life(at_effect(1 + 65534 * (dist(
        $self_x - (global(16) as fx) / 64,
        $self_y - (global(17) as fx) / 64) > 64fx)));
    set_accel(at_effect(0.1fx * (($self_age < 30) as fx)));
    wait(1);
    goto check_moon;
}

// st05bs:640-664: relative orbit centered on parent's FINAL at creation.
// Keep phase independent of movement velocity, 0.8deg/tick, radius 0->140/60.
async sub moon(cx: fx, cy: fx) {
    set_invuln(65535);
    set_hitbox(48fx);
    set_hurtbox(54fx);
    var t: int = 0;
    loop {
        var r: fx = 140fx;
        if t < 60 { r = 140fx * t / 60; }
        var theta: angle = (-16384 + (t * 65536) / 450) as angle;
        var x: fx = cx + r * cos(theta);
        var y: fx = cy + r * sin(theta);
        // Publish current source point before transforms; preset the next motion tick.
        set_global(16, (x * 64) as int);
        set_global(17, (y * 64) as int);
        var nr: fx = 140fx;
        if t + 1 < 60 { nr = 140fx * (t + 1) / 60; }
        var na: angle = (-16384 + ((t + 1) * 65536) / 450) as angle;
        move_vel_xy(0, cx + nr*cos(na) - $self_x,
            cy + nr*sin(na) - $self_y, EASE_LINEAR);
        t = t + 1;
        wait(1);
    }
}

// st05bs:741-816, async begins with 400-frame wait in either branch.
async sub stars() {
    wait(400);
    if global(GVAR_RANK) < 2 {
        var a: fx = -192fx;
        var direction: int = 0;
        loop {
            // Independent x, y, speed draws for each of the two emissions.
            for side in 0..2 {
                var base: fx = a;
                if side == 1 { base = -a; }
                var x: fx = base + ((rand(32768) as fx)/16384 - 1fx)*16fx;
                var y: fx = -16fx + (rand(32768) as fx)/512;
                var s: fx = 1fx + (rand(32768) as fx)/32768;
                // ANIM position -= 4*velocity; etAim3/one way points down.
                _ = fire(TH15_BIG_STAR_R, 3, x, y - 4*s, s, 90deg, none, none);
            }
            if direction == 0 {
                if a < 192fx { a = a + 24fx; } else { direction = 1; }
            } else {
                if a > -192fx { a = a - 24fx; } else { direction = 0; }
            }
            wait(12);
        }
    } else {
        loop {
            var ring_base: int = rand(65536) - 32768;
            for i in 0..32 {
                var ring_a: angle = (ring_base + (i*65536)/32) as angle;
                _ = fire(TH15_BIG_STAR_R, 3, $self_x - 4fx*cos(ring_a),
                    $self_y - 4fx*sin(ring_a), 1fx, ring_a, none, none);
            }
            wait(120);
        }
    }
}

async sub boss() {
    set_invuln(65535);
    set_hitbox(24fx);
    set_hurtbox(20fx);
    // BossCard1 flagSet3 disables body; entry cleanup has no inherited async/laser.
    set_enemy_flag(ENEMY_NO_BODY, 1);
    clear_bullets_at($self_x, $self_y, 640fx, 0);
    wait(2);
    wait(2); // source timerReset at entry +4
    kill_all_enemies(KILL_SILENT);
    clear_bullets_at($self_x, $self_y, 640fx, 0);
    move_vel_xy(0, 0fx, 0fx, EASE_LINEAR);
    // st05bs:615-616. Move stays within x±120,y80..304 limits.
    move_to(60, 0fx, 192fx, EASE_QUAD_OUT);
    wait(90);
    _ = spawn_enemy($self_x, $self_y, 100, 0, 0, 0, moon($self_x, $self_y));
    wait(60);
    spawn stars();
    // at(): E/N/H/L=4/8/10/12, radius sampled BEFORE its 1px increase.
    var ways: int = 4;
    if global(GVAR_RANK) == 1 { ways = 8; }
    if global(GVAR_RANK) == 2 { ways = 10; }
    if global(GVAR_RANK) == 3 { ways = 12; }
    var radius: fx = 0fx;
    var k: int = 0;
    loop {
        // Keep decimal source angular rates using a frame-derived phase.
        var a: angle = (16384 - (k*145640)/1000) as angle;
        var b: angle = (-38229 - (k*364092)/1000) as angle;
        var x: fx = $self_x + radius*cos(b);
        var y: fx = $self_y + radius*sin(b);
        if radius < 96fx { radius = radius + 1fx; }
        for i in 0..ways {
            var angle_i: angle = a + ((i*65536)/ways) as angle;
            // st05bs:709 ANIM retreat uses initial speed=4, hence 16px.
            _ = fire(TH15_FIREBALL_RED, 0, x - 16fx*cos(angle_i),
                y - 16fx*sin(angle_i), 4fx, angle_i, MOON_ERASABLE, none);
        }
        k = k + 1;
        wait(2);
    }
}
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 1, 0, 0, 0, boss);
}
async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    // Protect control from entry enmKillAll, which skips the source boss itself.
    set_enemy_flag(ENEMY_KILLALL_EXEMPT, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    kill_all_enemies(KILL_SILENT);
    clear_bullets();
    loop { wait(600); }
}
sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
